vector<int> endingLengths(const vector<int> &values) {
    vector<int> tails, lengths(values.size());
    for (int i = 0; i < static_cast<int>(values.size()); ++i) {
        auto position = lower_bound(tails.begin(), tails.end(), values[i]);
        int lengthIndex = static_cast<int>(position - tails.begin());
        if (position == tails.end()) tails.push_back(values[i]);
        else *position = values[i];
        lengths[i] = lengthIndex + 1;
    }
    return lengths;
}

